end

function PTLBDN_SetIds(t)
	PTLB_Load()
	local v = 0
	local i = 1
	while t[i] do v = PTLB_With(PTLB_DN, v, t[i]) i = i + 1 end
	PTLB_Apply(PTLB_T_DN, v)
	local n, a = PTLB_Count(PTLB_DN, v)
	Msg2Player("L\214nh B\181i D\222 Nh\169n: t\249 duy tr\215 " .. PTLB_DescDN(v) .. ".")
	if n == 0 then Msg2Player("B\185n ch\173a h\228c chi\170u n\181o trong b\233 n\181y: chi\170u h\228c sau s\207 t\249 \174\173\238c d\239ng.") end
	PTLBDN_After()
end

