-- after a set was chosen: start the auto fight (menu closed), or show the menu again (option off)
function PTLBDN_After()
	if GetTask(PTLB_T_PREF) == 0 then
		PTLB_StartAuto("L\214nh B\181i D\222 Nh\169n")
	else
		PTLBDN_Main()
	end
end

function PTLBDN_Main()
	PTLB_Load()
	local o = {}
	o[1] = "B\190t \174\199u t\249 \174\233ng \174\184nh/PTLBDN_Start"
	o[2] = "D\245ng t\249 \174\233ng \174\184nh/PTLBDN_Stop"
	o[3] = "B\233 t\202t c\182 buff (h\181o quang + B\230 T\169m Ch\243)/PTLBDN_Pre1"
	o[4] = "B\233 buff + ch\243 nguy\210n/PTLBDN_Pre2"
	o[5] = "Ch\228n t\245ng chi\170u (b\203t, t\190t).../PTLBDN_Groups"
	o[6] = "B\233 kh\184c, t\239y ch\228n, n\169ng c\202p k\252 n\168ng.../PTLBDN_More"
	o[7] = "\167\227ng/PTLB_No"
	PTLB_Say(PTLBDN_Title(), o)
end

function PTLBDN_Groups()
	PTLB_Load()
	local v = GetTask(PTLB_T_DN)
	local o = {}
	o[1] = "H\181o quang" .. " (" .. PTLB_GroupCount(PTLB_DN, v, 1) .. " \174ang b\203t)" .. "/PTLBDN_G1"
	o[2] = "H\229i m\184u v\181 ch\243 nguy\210n" .. " (" .. PTLB_GroupCount(PTLB_DN, v, 2) .. " \174ang b\203t)" .. "/PTLBDN_G2"
	o[3] = "Quay l\185i/PTLBDN_Main"
	o[4] = "\167\227ng/PTLB_No"
	PTLB_Say("<color=yellow>L\214nh B\181i D\222 Nh\169n<color>: ch\228n nh\227m chi\170u, r\229i b\202m t\245ng chi\170u \174\211 b\203t ho\198c t\190t. [B\203T] = t\249 \174\184nh d\239ng chi\170u \174\227. Ch\216 hi\214n chi\170u \174\183 h\228c.", o)
end

function PTLBDN_Group(g)
	PTLB_Load()
	local l = PTLB_GroupList(PTLB_DN, g)
	local v = GetTask(PTLB_T_DN)
	local names = { "H\181o quang", "H\229i m\184u v\181 ch\243 nguy\210n" }
	if getn(l) == 0 then
		Say("<color=yellow>L\214nh B\181i D\222 Nh\169n<color>: b\185n ch\173a h\228c chi\170u n\181o c\241a nh\227m " .. names[g] .. ".", 2, "Quay l\185i/PTLBDN_Groups", "\167\227ng/PTLB_No")
		return
	end
	local o = {}
	local n = 0
	local i = 1
	while l[i] do
		local s = PTLB_DN[l[i]]
		local m = "[t\190t] "
		if PTLB_Has(PTLB_DN, v, s.id) then m = "[B\203T] " end
		n = n + 1
		o[n] = m .. s.nm .. "/PTLBDN_T" .. l[i]
		i = i + 1
	end
	if n <= 5 then n = n + 1 o[n] = "Xong, b\190t \174\199u t\249 \174\233ng \174\184nh/PTLBDN_Start" end
	n = n + 1 o[n] = "Quay l\185i/PTLBDN_Groups"
	if n < 7 then n = n + 1 o[n] = "\167\227ng/PTLB_No" end
	PTLB_Say("<color=yellow>L\214nh B\181i D\222 Nh\169n<color>: nh\227m " .. names[g] .. " - b\202m m\233t chi\170u \174\211 b\203t ho\198c t\190t (\174ang b\203t " .. PTLB_GroupCount(PTLB_DN, v, g) .. ").", o)
end

function PTLBDN_G1() PTLBDN_Group(1) end
function PTLBDN_G2() PTLBDN_Group(2) end

-- toggle skill k of the table, then show its group page again
function PTLBDN_Toggle(k)
	PTLB_Load()
	local s = PTLB_DN[k]
	if not s or not PTLB_Learnt(s.id) then return end
	local v = GetTask(PTLB_T_DN)
	local on = nil
	if PTLB_Has(PTLB_DN, v, s.id) then v = PTLB_Without(PTLB_DN, v, s.id) else v = PTLB_With(PTLB_DN, v, s.id) on = 1 end
	local n, a = PTLB_Count(PTLB_DN, v)
	if n == 0 then v = 0 end
	PTLB_Apply(PTLB_T_DN, v)
	if on then Msg2Player("L\214nh B\181i D\222 Nh\169n: b\203t " .. s.nm) else Msg2Player("L\214nh B\181i D\222 Nh\169n: t\190t " .. s.nm) end
	PTLBDN_Group(s.grp)
end

