end

function PTLBDN_UpAllOk()
	local ok, n = PTLB_MaxAll(2)
	Msg2Player("L\214nh B\181i D\222 Nh\169n: \174\183 n\169ng t\232i \174a " .. ok .. " trong " .. n .. " k\252 n\168ng c\241a ph\184i.")
	PTLBDN_Up()
end

function PTLBDN_UpPage(pg)
	local l = PTLB_ProfList(2)
	local last = floor((getn(l) + 4) / 5)
	if last < 1 then last = 1 end
	if pg > last then pg = last end
	local o = {}
	local n = 0
	local i = (pg - 1) * 5 + 1
	while i <= pg * 5 and l[i] do
		local s = l[i]
		local lv = PTLB_Lv(s.id)
		local d = " (c\202p " .. lv .. " trong " .. s.mx .. ")"
		if lv <= 0 then d = " (ch\173a h\228c, t\232i \174a " .. s.mx .. ")" end
		if lv >= s.mx then d = " (\174\183 t\232i \174a " .. s.mx .. ")" end
		n = n + 1
		o[n] = s.nm .. d .. "/PTLBDN_U" .. s.id
		i = i + 1
	end
	if pg < last then n = n + 1 o[n] = "Trang sau " .. (pg + 1) .. "/PTLBDN_UP" .. (pg + 1) end
	n = n + 1 o[n] = "Quay l\185i/PTLBDN_Up"
	if n < 7 then n = n + 1 o[n] = "\167\227ng/PTLB_No" end
	PTLB_Say("<color=yellow>L\214nh B\181i D\222 Nh\169n<color>: ch\228n k\252 n\168ng \174\211 n\169ng l\170n c\202p t\232i \174a (trang " .. pg .. " " .. "trong " .. last .. ").", o)
end

function PTLBDN_UP1() PTLBDN_UpPage(1) end
function PTLBDN_UP2() PTLBDN_UpPage(2) end
function PTLBDN_UP3() PTLBDN_UpPage(3) end

function PTLBDN_UpOne(id)
	local s = PTLB_FindPS(2, id)
	if not s then return end
	if PTLB_Lv(id) >= s.mx then
		Msg2Player("L\214nh B\181i D\222 Nh\169n: " .. s.nm .. " \174\183 \235 c\202p t\232i \174a " .. s.mx .. ".")
		PTLBDN_UpShow(id)
		return
	end
	Say("<color=yellow>L\214nh B\181i D\222 Nh\169n<color>: n\169ng " .. s.nm .. " l\170n c\202p t\232i \174a " .. s.mx .. "?", 2, "\167\229ng \253/PTLBDN_Y" .. id, "Kh\171ng/PTLBDN_Up")
end

function PTLBDN_UpOk(id)
	local s = PTLB_FindPS(2, id)
	if not s then return end
	if PTLB_MaxOne(s) > 0 then
		Msg2Player("L\214nh B\181i D\222 Nh\169n: \174\183 n\169ng " .. s.nm .. " l\170n c\202p " .. s.mx .. ".")
	else
		Msg2Player("L\214nh B\181i D\222 Nh\169n: kh\171ng n\169ng \174\173\238c " .. s.nm .. ".")
	end
	PTLBDN_UpShow(id)
end

-- show the upgrade page holding skill id
function PTLBDN_UpShow(id)
	local s, pos = PTLB_FindPS(2, id)
	if pos < 1 then pos = 1 end
	PTLBDN_UpPage(floor((pos - 1) / 5) + 1)
end

